D[32400]={"^Strike with both weapons, dealing weapon damage per combo point%. Grants |cFFFFFFFFTitanic Power|r%.\n\n1 point: (.-)%% weapon damage%.\n2 points: (.-)%% weapon damage%.\n3 points: (.-)%% weapon damage%.\n4 points: (.-)%% weapon damage%.\n5 points: (.-)%% weapon damage%.\n\nDamage dealt is increased by 10%% if a Two%-Handed weapon is equipped%.%s*$","Golpeia com as duas armas, causando dano da arma por ponto de combo. Concede |cFFFFFFFFPoder Titânico|r.\n\n1 ponto: {{1}}% do dano da arma.\n2 pontos: {{2}}% do dano da arma.\n3 pontos: {{3}}% do dano da arma.\n4 pontos: {{4}}% do dano da arma.\n5 pontos: {{5}}% do dano da arma.\n\nO dano causado aumenta em 10% se uma arma de duas mãos estiver equipada."}
D[32401]={"^Strike with both weapons, dealing weapon damage per combo point%. Grants |cFFFFFFFFTitanic Power|r%.\n\n1 point: (.-)%% weapon damage%.\n2 points: (.-)%% weapon damage%.\n3 points: (.-)%% weapon damage%.\n4 points: (.-)%% weapon damage%.\n5 points: (.-)%% weapon damage%.\n\nDamage dealt is increased by 10%% if a Two%-Handed weapon is equipped%.\n\n10%% damage increase on next Warrior ability versus players%.\n\nTitanic Strike benefits from Impale%.%s*$","Golpeia com as duas armas, causando dano da arma por ponto de combo. Concede |cFFFFFFFFPoder Titânico|r.\n\n1 ponto: {{1}}% do dano da arma.\n2 pontos: {{2}}% do dano da arma.\n3 pontos: {{3}}% do dano da arma.\n4 pontos: {{4}}% do dano da arma.\n5 pontos: {{5}}% do dano da arma.\n\nO dano causado aumenta em 10% se uma arma de duas mãos estiver equipada.\n\nSua próxima habilidade de Guerreiro causa 10% a mais de dano contra jogadores.\n\nGolpe Titânico se beneficia de Empalar."}
D[32765]={"^Increases Nature damage by (.-)%%, Lightning Blade deals (.-)%% increased damage, and Lightning Blade, Thunder Clap, Chain Lightning and Lightning Bolt gains a (.-)%% chance to Overload%. This chance is tripled on critical hits%.%s*$","Aumenta em {{1}}% o dano de Natureza. Lâmina de Relâmpagos causa {{2}}% a mais de dano, e Lâmina de Relâmpagos, Trovoada, Cadeia de Raios e Raio têm {{3}}% de chance de ativar Sobrecarga. Essa chance é triplicada em acertos críticos."}
D[32766]={"^Increases Nature damage by (.-)%%, Lightning Blade deals (.-)%% increased damage, and Lightning Blade, Thunder Clap, Chain Lightning and Lightning Bolt gains a (.-)%% chance to Overload%. This chance is tripled on critical hits%.\n\nThe Overload chance is capped at 100%%, this increases the Lightning Overload chance for Lightning Bolt and Chain Lightning if known%. The duration of Electrified Onslaught cannot be refreshed%.%s*$","Aumenta em {{1}}% o dano de Natureza. Lâmina de Relâmpagos causa {{2}}% a mais de dano, e Lâmina de Relâmpagos, Trovoada, Cadeia de Raios e Raio têm {{3}}% de chance de ativar Sobrecarga. Essa chance é triplicada em acertos críticos.\n\nA chance de Sobrecarga é limitada a 100%. Se Sobrecarga de Raios for conhecida, essa chance também aumenta a chance de ativação dela para Raio e Cadeia de Raios. A duração de Investida Eletrificada não pode ser renovada."}
