D[47521]={"^|cff93cceaConsumes Carnage|r\nHurl a spear at an enemy dealing (.-)%% Ranged Weapon Damage plus (.-), increased by (.-)%% for each stack of |cffffffffCarnage|r consumed%. %$%?s705197\n\n%[Regenerates (.-)%% missing Energy%.\n\nThe cooldown of this ability is reset whenever you score a killing blow%.%]%[%]%s*$","|cff93cceaConsome Carnificina|r\nArremessa uma lança contra um inimigo, causando {{1}}% do dano da arma de longo alcance mais {{2}}, aumentado em {{3}}% para cada acúmulo de |cffffffffCarnificina|r consumido.$?s705197[\n\nRegenera {{4}}% da Energia perdida.\n\nA recarga desta habilidade é reiniciada sempre que você desfere um golpe fatal.][]"}
D[47666]={"^Whenever you shatter your |cffffffffImpaling Spear|r, affected enemies bleed for 100%% of the damage dealt over (.-)%.%s*$","Sempre que reventes seu |cffffffffLança Empaladora|r, os inimigos afetados se venha subjugados a uma hemorragia que lhes absorve 100% do dano causado durante {{1}}."}
D[47826]={"^Damage dealt by |cffffffffImpaling Spear|r |TInterface\\icons\\inv_ability_warrior_championsspear%.blp:0|t at its point of impact now causes the enemy to bleed for an additional 50%% of the damage dealt over 3 sec%.%s*$","O dano causado por |cffffffffLança Empaladora|r |TInterface\\icons\\inv_ability_warrior_championsspear.blp:0|t no ponto de impacto agora faz o inimigo sangrar por mais 50% do dano causado ao longo de 3 s."}
D[47827]={"^|cffffffffImpaling Spear|r |TInterface\\icons\\inv_ability_warrior_championsspear%.blp:0|t now causes your next 3 |cffffffffAxe Throws|r to strike an additional nearby enemy%. Lasts (.-)%.%s*$","|cffffffffLança Empaladora|r |TInterface\\icons\\inv_ability_warrior_championsspear.blp:0|t agora faz com que seus próximos 3 |cffffffffArremessos de Machado|r atinjam um inimigo adicional próximo. Dura {{1}}."}
D[48499]={"^\nYour Thunderstorm is transformed into |cFFFFFFFFAstral Storm|r%. This spell is castable while moving and benefits from modifiers to Thunderstorm%.\n\nIf Astral Storm is cast on a player afflicted by your Unrelenting Storm it will knock their soul out of their body, forcing your target and yourself into an alternate dimension for 8 seconds%.\nIf Astral Storm is cast on a monster, it will restore 10%% of your maximum mana%.%s*$","\nSua Trovoada é transformada em |cFFFFFFFFTempestade Astral|r. Este feitiço pode ser lançado em movimento e recebe os modificadores de Trovoada.\n\nSe Tempestade Astral for lançada em um jogador afetado por sua Tempestade Implacável, a alma dele será arrancada do corpo, levando vocês dois para uma dimensão alternativa durante 8 s.\nSe Tempestade Astral for lançada em um monstro, restaura 10% da sua mana máxima."}
D[48500]={"^You call down spiritual ancestors to damage your target, dealing (.-) Astral damage, knocking them back 20 yards%.  This ability is not interrupted by movement, and scales with your Thunderstorm ability%.\n\nIf Astral Storm is cast on a player afflicted by your Unrelenting Storm, it will knock the spirit of your target out of their body, forcing your target and yourself into an alternate dimension for 8 seconds%.%s*$","Invoca ancestrais espirituais para atingir o alvo, causando {{1}} de dano Astral e repelindo-o por 20 m. Esta habilidade pode ser lançada em movimento e escala com sua Trovoada.\n\nSe Tempestade Astral for lançada em um jogador afetado por Tempestade Implacável, o espírito dele será arrancado do corpo, levando você e o alvo para uma dimensão alternativa durante 8 s."}
