D[65055]={"^Instantly generates 5 stacks of |cff8fff7aAdvantage|r and resets the cooldown of |cffffffffBallista Shot|r, |cffffffffWoodland Adept|r and |cffffffffWarmaster Shot|r%.%s*$","Gera instantaneamente 5 acúmulos de |cff8fff7aVantagem|r e reinicia a recarga de |cffffffffTiro de Balista|r, |cffffffffExperto do Floresta|r e |cffffffffDisparo de Mestre|r."}
D[65056]={"^Enrage and challenge an enemy to a duel to the death for (.-), reducing their healing taken by (.-)%%%. Only usable on enemies below 50%% maximum health%.\n\nDealing damage to them increases your movement speed and healing received by (.-)%%, for 6 sec, stacking 5 times%.\n\nIf the enemy dies while marked, reduce the cooldown of this ability by 30 sec and heal for 10%% maximum health%.%s*$","Enfurece e desafia um inimigo para um duelo até a morte durante {{1}}, reduzindo em {{2}}% a cura que ele recebe. Só pode ser usada contra inimigos com menos de 50% da vida máxima.\n\nCausar dano ao alvo aumenta sua velocidade de movimento e a cura recebida em {{3}}% durante 6 s, acumulando até 5 vezes.\n\nSe o inimigo morrer enquanto estiver marcado, a recarga desta habilidade é reduzida em 30 s e você recupera 10% da vida máxima."}
D[65058]={"^Dealing damage to this target reduces their movement speed by (.-)%% for (.-), stacking 4 times%.\n\nAt 4 stacks, the next instance of damage will knock the spear off and lodge it into the ground, boosting morale, and reducing the duration of fear and stun effects on allies within 15 yds by 20%% for 8 sec%.%s*$","Causar dano a este alvo reduz a velocidade de movimento dele em {{1}}% durante {{2}}, acumulando até 4 vezes.\n\nAo atingir 4 acúmulos, a próxima ocorrência de dano desprende a lança e a crava no chão, elevando o moral e reduzindo em 20% a duração de efeitos de medo e atordoamento nos aliados em um raio de 15 m durante 8 s."}
D[65062]={"^Attempt to break an enemy's jaw, interrupting them and preventing any spell from that school from being cast for (.-)%.\n\nSuccessfully interrupting a target increases your haste by (.-)%% for (.-) and refunds half the cost of this ability%.%s*$","Tenta quebrar a mandíbula de um inimigo, interrompendo-o e impedindo a conjuração de qualquer feitiço dessa escola durante {{1}}.\n\nInterromper um alvo com sucesso aumenta sua aceleração em {{2}}% durante {{3}} e restitui metade do custo desta habilidade."}
D[65063]={"^Attempt to break an enemy's jaw, interrupting them and preventing any spell from that school from being cast for (.-)%.%s*$","Tenta quebrar a mandíbula de um inimigo, interrompendo-o e impedindo a conjuração de qualquer feitiço dessa escola durante {{1}}."}
D[65133]={"^|cffec8201Enrage Effect|r\nEnrage, increasing your melee haste and critical strike chance by (.-)%%, but increasing your Physical Damage taken by (.-)%% for (.-)%. \n\nPhysical Damage has a (.-)%% chance to extend this effect by (.-) sec%.%s*$","|cffec8201Efeito de Enfurecimento|r\nEnfurece, aumentando em {{1}}% sua aceleração e chance de acerto crítico corpo a corpo, mas aumentando em {{2}}% o dano Físico recebido durante {{3}}.\n\nDano Físico recebido tem {{4}}% de chance de estender este efeito em {{5}} s."}
D[65169]={"^You prepare yourself to dominate your foes, reducing your Energy costs by (.-)%% and causing killing enemies that yield experience or honor to grant you |cffffffffBorn in Blood|r%. Lasts for (.-)%.%s*$","Te preparas para domínio a seus inimigos, reduzindo seus custos de Energia em {{1}}% e fazendo com que matar inimigos que concedem experiência ou honra te conceda |cffffffffNascido no Sangue|r. Dura {{2}}."}
D[65233]={"^While enraged, the global cooldown of Barbarian abilities is reduced by 30%%%.%s*$","Enquanto estiver enfurecido, a recarga global das habilidades do Bárbaro é reduzido em 30%."}
D[65290]={"^Increases Energy by 30%%%.%s*$","Aumenta a Energia em 30%."}
