D[76706]={"^Extending duration of Recklessfury by 2 sec when barbaric strike is cast%.%s*$","Estende a duração de Fúria Desenfreada em 2 s quando se lança Golpe Bárbaro."}
D[76825]={"^Damage dealt by |cffffffffStorm of Steel|r now triggers |cffffffffSavagery|r%.%s*$","O dano causado por |cffffffffTempestade de Aço|r agora ativa |cffffffffSelvageria|r."}
D[76826]={"^Increases the duration of |cffffffffMaximum Carnage|r by (.-) sec and it now grants |cffffffffUtter Devastation|r for (.-)%.%s*$","Aumenta a duração de |cffffffffCarnificina Máxima|r em {{1}} s e agora concede |cffffffffDevastação total|r durante {{2}}."}
D[76829]={"^Melee attack speed increased by (.-)%%, stacking (.-) times, for (.-)%.\n\nUpon reaching 8 stacks, |cFFFFFFFFRipper|r will go on cooldown for 20 seconds%.%s*$","A velocidade de ataque corpo a corpo aumenta em {{1}}%, acumulando até {{2}} vezes, durante {{3}}.\n\nAo atingir 8 acúmulos, |cFFFFFFFFRasgador|r entra em recarga por 20 s."}
D[76886]={"^|cfffffffffConsumes Carnage|r\nStrike an enemy for (.-)%% Weapon Damage plus (.-) with both weapons and increase melee attack speed by (.-)%% for (.-), stacking (.-) times%.\n\nConsumes 1 stack of |cffffffffCarnage|r to deal (.-) additional Physical Damage%. Has no cooldown below 8 stacks%.%s*$","|cfffffffffConsumes Carnificina|r\nGolpeia um inimigo em {{1}}% de dano da arma mais {{2}} com as duas armas e aumenta a velocidade de ataque corpo a corpo em {{3}}% durante {{4}}, acumulando-se {{5}} vezes.\n\nConsome 1 acúmulo de |cffffffffCarnificina|r para causar {{6}} de dano Físico adicional. Não tem recarga abaixo de 8 acúmulos."}
D[76899]={"^Subsequent |cffffffffAncestral Strikes|r and |cffffffffCrush\\r now deal (.-) increased damage to the target for 15 sec, stacking 3 times%.%s*$","Aumenta o dano dos seguintes |cffffffffGolpes ancestrais|r e |cffffffffEsmagar em {{1}}% durante 15 s ao alvo, acumulando-se 3 vezes.|r"}
D[76947]={"^|cFF66DDFFLevel 15 Passive|r\nTransforms |cffffffffBarbaric Whirl|r into |cffffffffAxe Volley|r%.%s*$","|cFF66DDFFPassivo de Nível 15|r\nTransforma |cffffffffRedemoinho Bárbaro|r em |cffffffffSalva de Machados|r."}
D[76948]={"^|cFF66DDFFLevel 15 Passive|r\nDecapitate now deals additional damage for each point of Energy spent above 100%.%s*$","|cFF66DDFFPassivo de Nível 15|r\nDecapitar agora causa um dano adicional para cada ponto de Energia gastado acima de 100."}
D[77460]={"^Increases the critical strike chance of |cffffffffSavage Strike|r by (.-)%% and causes it to strike 1 additional nearby enemy%.%s*$","Aumenta em {{1}}% a chance de acerto crítico de |cffffffffGolpe Selvagem|r e faz a habilidade atingir 1 inimigo próximo adicional."}
D[77461]={"^Increases the critical strike chance of |cffffffffSavage Strike|r by (.-)%% and causes it to strike 2 additional nearby enemies%.%s*$","Aumenta em {{1}}% a chance de acerto crítico de |cffffffffGolpe Selvagem|r e faz a habilidade atingir 2 inimigos próximos adicionais."}
D[77471]={"^Disables the use of |cffffffffCrushing Slam|r and teaches you |cffffffffImpaling Spear|r and |cffffffffBerserker Axe|r%.%s*$","Desabilita o uso de |cffffffffGolpe Esmagador|r ensina |cffffffffLança Empaladora|r e |cffffffffMachado Berserker|r."}
D[77540]={"^Enrage, rapidly draining Energy over (.-), removing the cost of |cffffffffBerserker Axe|r and guaranteeing it to critically strike%.\n\nWhile active, critical strikes reduce the cooldown of |cffffffffBerserker|r by (.-) sec%.\n\nUsing this ability transforms it into |cffffffffSpite|r%.%s*$","Enfurecer-se, drenando Energia rapidamente durante {{1}}, removendo o custo de |cffffffffMachado Berserker|r e garantindo que golpeie criticamente.\n\nEnquanto está ativo, os acertos críticos reduzem a recarga de |cffffffffFuror|r em {{2}} s.\n\nUsar esta habilidado transforma em |cffffffffMaldade|r."}
D[77564]={"^|cFF66DDFFLevel 10 Passive|r\nAuto attacks while wielding a two%-handed weapon now have a (.-)%% chance to unleash |cffffffffGrasp of the Undying|r, leeching (.-) health from the target%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nAtaques automáticos enquanto você empunha uma arma de duas mãos agora têm {{1}}% de chance de liberar |cffffffffGarra do Imortal|r, drenando {{2}} de vida do alvo."}
D[77636]={"^Your |cffffffffGrasp of the Undying|r now strikes 2 additional nearby enemies%.%s*$","Sua |cffffffffGarra do Imortal|r agora atinge 2 inimigos adicionais próximos."}
D[77689]={"^|cFF66DDFFLevel 10 Passive|r\nAuto attacks while wielding a two%-handed weapon now have a (.-)%% chance to unleash |cffffffffGrasp of the Undying|r, leeching (.-) health from the target%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nAtaques automáticos enquanto você empunha uma arma de duas mãos agora têm {{1}}% de chance de liberar |cffffffffGarra do Imortal|r, drenando {{2}} de vida do alvo."}
D[79136]={"^|cff93cceaConsumes Carnage|r\nHurl a spear at an enemy dealing (.-)%% Ranged Weapon Damage plus (.-), increased by (.-)%% for each stack of |cffffffffCarnage|r consumed%. %$%?s705197\n\n%[Regenerates (.-)%% missing Energy%.\n\nThe cooldown of this ability is reset whenever you score a killing blow%.%]%[%]%s*$","|cff93cceaConsome Carnificina|r\nArremessa uma lança contra um inimigo, causando {{1}}% do dano da arma de longo alcance mais {{2}}, aumentado em {{3}}% para cada acúmulo de |cffffffffCarnificina|r consumido.$?s705197[\n\nRegenera {{4}}% da Energia perdida.\n\nA recarga desta habilidade é reiniciada sempre que você desfere um golpe fatal.][]"}
D[79170]={"^Whenever you shatter your |cffffffffImpaling Spear|r, affected enemies bleed for 100%% of the damage dealt over (.-)%.%s*$","Sempre que reventes seu |cffffffffLança Empaladora|r, os inimigos afetados se venha subjugados a uma hemorragia que lhes absorve 100% do dano causado durante {{1}}."}
D[79203]={"^Damage dealt by |cffffffffImpaling Spear|r |TInterface\\icons\\inv_ability_warrior_championsspear%.blp:0|t at its point of impact now causes the enemy to bleed for an additional 50%% of the damage dealt over 3 sec%.%s*$","O dano causado por |cffffffffLança Empaladora|r |TInterface\\icons\\inv_ability_warrior_championsspear.blp:0|t no ponto de impacto agora faz o inimigo sangrar por mais 50% do dano causado ao longo de 3 s."}
D[79204]={"^|cffffffffImpaling Spear|r |TInterface\\icons\\inv_ability_warrior_championsspear%.blp:0|t now causes your next 3 |cffffffffAxe Throws|r to strike an additional nearby enemy%. Lasts (.-)%.%s*$","|cffffffffLança Empaladora|r |TInterface\\icons\\inv_ability_warrior_championsspear.blp:0|t agora faz com que seus próximos 3 |cffffffffArremessos de Machado|r atinjam um inimigo adicional próximo. Dura {{1}}."}
D[79517]={"^\nYour Thunderstorm is transformed into |cFFFFFFFFAstral Storm|r%. This spell is castable while moving and benefits from modifiers to Thunderstorm%.\n\nIf Astral Storm is cast on a player afflicted by your Unrelenting Storm it will knock their soul out of their body, forcing your target and yourself into an alternate dimension for 8 seconds%.\nIf Astral Storm is cast on a monster, it will restore 10%% of your maximum mana%.%s*$","\nSua Trovoada é transformada em |cFFFFFFFFTempestade Astral|r. Este feitiço pode ser lançado em movimento e recebe os modificadores de Trovoada.\n\nSe Tempestade Astral for lançada em um jogador afetado por sua Tempestade Implacável, a alma dele será arrancada do corpo, levando vocês dois para uma dimensão alternativa durante 8 s.\nSe Tempestade Astral for lançada em um monstro, restaura 10% da sua mana máxima."}
D[79518]={"^You call down spiritual ancestors to damage your target, dealing (.-) Astral damage, knocking them back 20 yards%.  This ability is not interrupted by movement, and scales with your Thunderstorm ability%.\n\nIf Astral Storm is cast on a player afflicted by your Unrelenting Storm, it will knock the spirit of your target out of their body, forcing your target and yourself into an alternate dimension for 8 seconds%.%s*$","Invoca ancestrais espirituais para atingir o alvo, causando {{1}} de dano Astral e repelindo-o por 20 m. Esta habilidade pode ser lançada em movimento e escala com sua Trovoada.\n\nSe Tempestade Astral for lançada em um jogador afetado por Tempestade Implacável, o espírito dele será arrancado do corpo, levando você e o alvo para uma dimensão alternativa durante 8 s."}
D[79647]={"^\nUnleash a shadowy onslaught of despairing souls dealing (.-) Shadow damage to up to (.-) targets%.%s*$","\nLiberar um ataque sombrio de almas desesperadas causando {{1}} de dano de Sombra até {{2}} alvos."}
D[80290]={"^Damaging Hunter ability casts grant |cFFFFFFFFUnrelenting Assault|r%. At (.-) stacks, gain a charge of |cFFFFFFFFUnrelenting Wrath|r%.\n\nKill Command effectiveness and Frenzy Shot damage is increased by (.-)%% and Kill Shot damage is increased by (.-)%%%.\n\nTriggering Beast Within reduces the cooldown of Frenzy Shot by (.-) sec%. The duration of Bestial Wrath and Beast Within is increased by (.-) sec%.%s*$","Lançar habilidades de Caçador que causam dano concede |cFFFFFFFFAssalto Implacável|r. Ao atingir {{1}} acúmulos, você recebe uma carga de |cFFFFFFFFRaiva Implacável|r.\n\nA eficácia de Comando para Matar e o dano de Disparo Frenético aumentam em {{2}}%, e o dano de Tiro Mortal aumenta em {{3}}%.\n\nAtivar Fera Interior reduz em {{4}} s a recarga de Disparo Frenético. A duração de Ira Bestial e Fera Interior aumenta em {{5}} s."}
D[80291]={"^Damaging Hunter ability casts grant |cFFFFFFFFUnrelenting Assault|r%. At (.-) stacks, gain a charge of |cFFFFFFFFUnrelenting Wrath|r%.\n\nYou can only gain |cFFFFFFFFUnrelenting Assault|r stacks once per ability cast%.\n\nKill Command effectiveness and Frenzy Shot damage is increased by (.-)%% and Kill Shot damage is increased by (.-)%%%.\n\nTriggering Beast Within reduces the cooldown of Frenzy Shot by (.-) sec%. The duration of Bestial Wrath and Beast Within is increased by (.-) sec%.%s*$","Lançamentos de habilidades de Caçador que causam dano concedem |cFFFFFFFFAssalto Implacável|r. Ao atingir {{1}} acúmulos, você ganha uma carga de |cFFFFFFFFRaiva Implacável|r.\n\nVocê só pode ganhar acúmulos de |cFFFFFFFFAssalto Implacável|r uma vez por lançamento de habilidade.\n\nA eficácia de |cFFFFFFFFComando para Matar|r e o dano de |cFFFFFFFFDisparo Frenético|r aumentam em {{2}}%, e o dano de |cFFFFFFFFTiro Mortal|r aumenta em {{3}}%.\n\nAtivar Fera Interior reduz em {{4}} s a recarga de |cFFFFFFFFDisparo Frenético|r. A duração de Raiva Bestial e Fera Interior aumenta em {{5}} s."}
D[80292]={"^\nSend your pet into a rage causing (.-)%% increased damage for (.-), and an additional (.-)%% with special attacks, reduces all threat generated by your pet by (.-)%%%.\nCauses your pet to tear through enemies within (.-) yards, increasing damage taken from your pet by (.-)%%, inflicting Physical damage and additional damage over time for (.-)%.%s*$","Faz seu mascote entrar em fúria, aumentando em {{1}}% o dano causado durante {{2}} em mais {{3}}% o dano dos ataques especiais, além de reduzir em {{4}}% toda a ameaça gerada.\nFaz o mascote dilacerar inimigos em um raio de {{5}} m, aumentando em {{6}}% o dano que você recebe dele causando dano Físico adicional ao longo de {{7}}."}
D[80293]={"^\nSend your pet into a rage causing (.-)%% increased damage for (.-), and an additional (.-)%% with special attacks, reduces all threat generated by your pet by (.-)%%%.\nCauses your pet to tear through enemies within (.-) yards, increasing damage taken from your pet by (.-)%%, inflicting Physical damage and additional damage over time for (.-)%.\n\nUnrelenting Wrath will trigger The Beast Within if the last rank is known, but it will not make you immune to crowd%-control effects%.%s*$","Faz seu mascote entrar em fúria, aumentando em {{1}}% o dano causado durante {{2}} em mais {{3}}% o dano dos ataques especiais, além de reduzir em {{4}}% toda a ameaça gerada.\nFaz o mascote dilacerar inimigos em um raio de {{5}} m, aumentando em {{6}}% o dano que você recebe dele causando dano Físico adicional ao longo de {{7}}.\n\nFúria Inexorável ativa Fera Interior caso o último grau seja conhecido, mas não concede imunidade a efeitos de controle coletivo."}
D[80997]={"^Using Rupture on a target afflicted by your Rend will trigger a violent attack, dealing 60%% weapon damage and applying Rend %(if known%) to up to 10 targets around you%. Your Rupture spell now has a 5 second cooldown%.\n\nDoes not work with Hydra's Venom, Spell Shredder or Carnage Incarnate Mystic Enchantments%.%s*$","Usar Ruptura em um alvo afetado por Dilacerar desencadeia um ataque violento, causando 60% do dano da arma e aplicando Dilacerar (se conhecido) a até 10 alvos ao seu redor. Ruptura passa a ter 5 s de recarga.\n\nNão funciona com os Encantamentos Místicos Veneno da Hidra, Dilacerante de Feitiços ou Carnificina Encarnada."}
D[81006]={"^Sinister Strike is transformed into Sinister Throw%. Each Enhancement Shaman Weapon Enchant you know unlocks an Empowered Throw%. These Throw abilities require 2 daggers, generate combo points and cost energy%. Deadly Throw Deals 200%% more damage%.\n\nRockbiter Throw shatters on impact, causing nearby targets to bleed for 12 seconds, stacks up to 5%.\n\nFlametongue Throw deals fire damage and dispels one beneficial magic effect%.\n\nFrostbrand Throw deals frost damage and slows your target%.\n\nWindfury Throw causes your to become a blur, enabling the use of abilities that require stealth for 4 second%.%s*$","Golpe Sinistro é transformado em Lançamento Sinistro. Cada Encantamento de Arma de Xamã de Aperfeiçoamento conhecido libera um Arremesso Fortalecido. Essas habilidades exigem 2 adagas, geram pontos de combo e consomem Energia. Arremesso Mortal causa 200% a mais de dano.\n\nArremesso Trinca-pedra se estilhaça no impacto, fazendo os alvos próximos sangrarem durante 12 s, acumulando até 5 vezes.\n\nArremesso Língua de Fogo causa dano de Fogo e dissipa um efeito mágico benéfico.\n\nArremesso Marca Gélida causa dano de Gelo e reduz a velocidade do alvo.\n\nArremesso Fúria dos Ventos deixa seus movimentos indistintos, permitindo o uso de habilidades que exigem Furtividade durante 4 s."}
D[81023]={"^Fingers of Frost also grants you a single charge of Fingers of the Storm%. Fingers of the Storm increases the damage and critical strike chance of your next Shaman Shock by 50%%, and extends the duration of your active Booming Echoes buffs by 3 seconds%.\n\nIce Lance is transformed into Froststorm Strike%. While Fingers of Frost is Active, Froststorm Lance jumps to 2 additional enemies%.\n\nLightning Bolt and Chain Lightning apply a stack of Charged Ice, enabling your Lightning Bolt and Chain Lightning to trigger Fingers of Frost and increasing the chance of triggering Fingers of Frost by 5%% per stack%. Stacks up to 20%.\n\nFrostbolt can now consume Unrelenting Storm on enemies to deal 200%% increased damage%.%s*$","Dedos de Gelo também concede uma carga de Dedos da Tempestade. Dedos da Tempestade aumenta em 50% o dano e a chance de acerto crítico do seu próximo Choque Xamânico e prolonga em 3 s a duração dos seus efeitos ativos de Ecos Retumbantes.\n\nLança de Gelo é transformada em Golpe da Tempestade Gélida. Enquanto Dedos de Gelo estiver ativo, Lança da Tempestade Gélida salta para 2 inimigos adicionais.\n\nRaio e Cadeia de Raios aplicam um acúmulo de Gelo Carregado, permitindo que essas habilidades ativem Dedos de Gelo e aumentando em 5% por acúmulo a chance de ativá-lo. Acumula até 20 vezes.\n\nSeta de Gelo agora pode consumir Tempestade Implacável dos inimigos para causar 200% a mais de dano."}
D[81075]={"^Unrelenting Storm Froststorm%s*$","Tempestade incessante Geadatormenta."}
D[81205]={"^When you critically heal with your Healing Wave, Holy Light, Lesser Healing Wave or Riptide you summon an Ancestral spirit to aid you, instantly healing the lowest percentage health friendly party or raid target within 40 yards for (.-)%% of the amount healed%.%s*$","Quando você realiza uma cura crítica com Onda de Cura, Luz Sagrada, Onda de Cura Menor ou Contracorrente, evoca um Espírito Ancestral para ajudá-lo, curando instantaneamente em {{1}}% do valor curado o aliado do grupo ou raide com a menor porcentagem de vida em um raio de 40 m."}
D[81563]={"^\nThe cooldown on your Healing Rain is increased by x%. %(probably want to move it towards a Tranq CD with this%)\nWhile active your Shaman healing spell criticals apply Ancestral Awakening on up to 5 players affected by it%.%s*$","\nA recarga de sua Chuva Curativa aumenta em x.\nEnquanto estiver ativo, seus curas críticas com feitiços curativos do xamã aplicam Despertar Ancestral até 5 jogadores afetados por ele."}
D[81653]={"^\nCharge an enemy, generate (.-) rage, dealing (.-)%% weapon damage%.\n\n|cFFFFFFFFThis ability can be used in melee range and doesn't generate threat%.|r%s*$","\nInveste contra um inimigo, gera {{1}} de raiva e causa {{2}}% do dano da arma.\n\n|cFFFFFFFFEsta habilidade pode ser usada em alcance corpo a corpo e não gera ameaça.|r"}
