D[81796]={"^\nCharge an enemy, generate (.-) rage, dealing (.-)%% weapon damage%.\n\n|cFFFFFFFFThis ability can be used in melee range and doesn't generate threat%.|r\n\nThe Anger Management capstone triggered buff is reduced by 50%% while Battle Fervor is equipped%.%s*$","\nInveste contra um inimigo, gera {{1}} de raiva e causa {{2}}% do dano da arma.\n\n|cFFFFFFFFEsta habilidade pode ser usada em alcance corpo a corpo e não gera ameaça.|r\n\nO benefício ativado pelo talento final Controle da Raiva é reduzido em 50% enquanto Fervor de Batalha estiver equipado."}
D[81870]={"^\nSend your pet into a rage causing (.-)%% additional damage for (.-), and reducing all threat generated by your pet (.-)%%%.\n\nResets the cooldown of your |cFFFFFFFFFrenzy Shot|r%.%s*$","\nColoca seu mascote em fúria, fazendo-o causar {{1}}% de dano adicional durante {{2}} e reduzindo em {{3}}% toda a ameaça gerada por ele.\n\nReinicia a recarga de |cFFFFFFFFDisparo Frenético|r."}
D[81871]={"^\nSend your pet into a rage causing (.-)%% additional damage for (.-), and reducing all threat generated by your pet (.-)%%%.\n\nResets the cooldown of your |cFFFFFFFFFrenzy Shot|r%.\n\nUnrelenting Wrath will trigger The Beast Within if the last rank is known, but it will not make you immune to crowd%-control effects%.%s*$","\nColoca seu mascote em fúria, aumentando o dano causado em {{1}}% durante {{2}} e reduzindo em {{3}}% toda a ameaça gerada por ele.\n\nReinicia a recarga de |cFFFFFFFFDisparo Frenético|r.\n\nRaiva Implacável ativa Fera Interior se você conhecer o grau final, mas não concede imunidade a efeitos de controle coletivo."}
D[81926]={"^\nTaste for Blood now empowers your next Swipe to generate additional threat and draw blood from all enemies hit, stacks up to 12 times%. |cFFFFFFFFMaul|r and |cFFFFFFFFRend %(Carnage%)|r ticks also have a chance to draw blood%. \n\nIf you get hit below 50%% health, you will consume some of this blood to heal yourself%. This effect can only occur once every 10 seconds%.\nIf you reach max stacks you become |cFFFFFFFFCarnage Incarnate|r%.%s*$","\nGosto por Sangue agora fortalece sua próxima Patada, fazendo-a gerar ameaça adicional e extrair sangue de todos os inimigos atingidos, acumulando até 12 vezes. Os pulsos de |cFFFFFFFFMalho|r e |cFFFFFFFFDesgarrar (Carnificina)|r também têm chance de extrair sangue.\n\nSe você sofrer dano enquanto estiver com menos de 50% de vida, consumirá parte desse sangue para se curar. Este efeito só pode ocorrer uma vez a cada 10 s.\nAo atingir o máximo de acúmulos, você se torna |cFFFFFFFFCarnificina Encarnada|r."}
D[82655]={"^Dealing damage with |cFFFFFFFFThunderstorm|r restores (.-)%% of your maximum mana and knocks players back%.\n\nIf the player is afflicted by your |cFFFFFFFFUnrelenting Storm|r it will force you and your target into an alternate dimension for 8 seconds%.%s*$","Causar dano com |cFFFFFFFFTrovoada|r restaura {{1}}% da sua mana máxima e repele jogadores.\n\nSe um jogador estiver afetado por sua |cFFFFFFFFTempestade Implacável|r, você e o alvo serão transportados para uma dimensão alternativa durante 8 s."}
D[83114]={"^Unleash a shadowy onslaught, dealing (.-) Shadow damage to (.-) enemies%.%s*$","Liberar um ataque sombrio que causa {{1}} de dano de Sombra a {{2}} inimigos."}
D[83305]={"^Teaches you: Unrelenting Wrath%.%s*$","Ensina: Raiva Implacável."}
D[83341]={"^Teaches you: Carnage Incarnate%.%s*$","Ensina: Carnificina Encarnada."}
D[83342]={"^Teaches you: Carnage Rend%.%s*$","Ensina: Dilacerar Carnificina."}
D[84855]={"^|cffFFFFFFCreature Affix|r\n|cffFF9000Unrelenting Spirits|r rises from the corpses of non%-boss enemies and pursue a random player%. If the player is not in melee range, they will cast Unrelenting Pain%.%s*$","|cffFFFFFFAfixo de Criatura|r\n|cffFF9000Espíritos Implacáveis|r surgem dos cadáveres de inimigos que não sejam chefes e perseguem um jogador aleatório. Se o jogador não estiver em alcance corpo a corpo, eles lançarão Dor Implacável."}
D[85110]={"^Returns the spirit to the body, restoring a dead target to life with (.-) health and (.-) mana%.  Cannot be cast when in combat%.%s*$","Devolva o espírito ao corpo, restaurando um alvo morto à vida com {{1}} vida e {{2}} mana. Não é possível lançar durante combate."}
D[85668]={"^Intimidates an enemy, causing it to flee in terror for (.-)%. Only 1 target can be feared at a time%.%s*$","Intimida um inimigo, fazendo com que fuja presa do terror durante {{1}}. Só pode inculcar medo a 1 alvo por vez."}
D[85939]={"^Heals a friendly target for (.-) and another (.-) over (.-)%.%s*$","Cura um alvo aliado em {{1}} e outro {{2}} sobre {{3}}."}
D[86240]={"^Inflicts Physical damage to an enemy every (.-) sec%. for (.-)%.%s*$","Causa dano Físico a um inimigo a cada {{1}} s durante {{2}}."}
D[86932]={"^Increases your Intellect by (.-)%%%.%s*$","Aumenta seu Intelecto {{1}}%."}
D[87758]={"^Target and impale the corpse of any of the vrykul in the greater Jotunheim region%.  Range is (.-) yards%.%s*$","Selecione e empale o cadáver de qualquer vrykul na região de Jotunheim. Alcance: {{1}} m."}
D[87769]={"^Forces all warriors near the caster into Berserker stance for (.-), increasing their damage taken by (.-)%%%.%s*$","Obriga a todos guerreiros que se encontrem perto do conjurador a entrar em atitude rabiosa durante {{1}}, aumenta o dano que você recebe em {{2}}%."}
D[87891]={"^Attempts to decapitate the target, causing (.-) damage%.%s*$","Tenta decapitar o alvo, causa {{1}} de dano."}
D[87930]={"^Command your pet to intimidate the target, causing a high amount of threat and stunning the target for (.-)%. Lasts (.-)%.%s*$","Ordena que seu mascote que intimide o alvo, causando um alto nível de ameaça e atordoar ao alvo durante {{1}}. Dura {{2}}."}
D[88091]={"^Chance to decapitate the target on a melee swing, causing (.-) damage%.%s*$","Chance de decapitar o alvo em um golpe corpo a corpo, causando {{1}} de dano."}
D[88230]={"^The caster goes berserk, becoming unstoppable%. Increases attack speed by (.-)%.%s*$","O conjurador senfurece torna-se imparável. Aumenta a velocidade de ataque {{1}} p."}
D[88238]={"^Increases the caster's attack and movement speeds by (.-)%% and all damage it deals by (.-)%% for (.-)%.  Also grants immunity to Taunt effects%.%s*$","aumenta em {{1}}% a velocidade de movimento e de ataque do conjurador e todo o dano que causa {{2}}% durante {{3}}. Também concede imunidade aos efeitos de Provocar."}
D[88361]={"^Increases the caster's movement speed by (.-)%% and the damage it deals by (.-)%% for (.-)%.%s*$","aumenta em {{1}}% a velocidade de movimento do conjurador e o dano que causa {{2}}% durante {{3}}."}
D[88520]={"^Increases damage dealt by (.-)%%%.%s*$","Aumenta o dano causado {{1}}%."}
D[88745]={"^Inflicts (.-) Physical damage to an enemy every (.-) sec%. for (.-)%.%s*$","Causa {{1}} de dano Físico a um inimigo a cada {{2}} s durante {{3}}."}
D[88775]={"^Calls forth an ancestral spirit wolf to track the individual you seek%.%s*$","Chama a um espírito de lobo ancestral para que rastreie a quem caso."}
D[89685]={"^Hurls your axe in an attempt to decapitate your target causing (.-) damage%.%s*$","lança seu machado com o alvo decapitar a seu oponente causando {{1}} de dano."}
D[89857]={"^Increases the damage dealt by the caster by (.-)%%%.%s*$","Aumenta o dano causado pelo conjurador {{1}}%."}
D[90982]={"^Increases the caster's attack speed by (.-)%% and all damage it deals by (.-)%% for (.-)%.%s*$","aumenta em {{1}}% a velocidade de ataque do conjurador e todo o dano Físico que causa {{2}}% durante {{3}}."}
D[91041]={"^Throws your weapon, inflicting its (.-) damage on the target%.%s*$","Lança sua arma e causa {{1}} de seu dano ao alvo."}
D[91042]={"^Hurls a volley of Axes%.%s*$","Lança uma salva de machados."}
D[91448]={"^Impale the corpse of an Emissary of Hate with the banner of the Shattered Sun Offensive%.%s*$","Empala o cadáver de um Emissário do Ódio com o estandarte da Ofensiva Sol Partido."}
D[91801]={"^Impale Leviroth while he slumbers in the waters below Riplash%.%s*$","Empala a Leviroth enquanto dorme nas águas baixo Tralhadón."}
D[91972]={"^Throw at the Scarlet Onslaught Prisoner in Venomspite to dissolve him into goo%.%s*$","Arremesse no Prisioneiro do Embate Escarlate em Rancor Venenoso para dissolvê-lo em gosma."}
D[91988]={"^Throws a spear at a target, dealing (.-) damage and an additional (.-) damage every (.-) sec%. for (.-)%.%s*$","Arremessa uma lança no alvo, causando {{1}} de dano e mais {{2}} de dano a cada {{3}} s durante {{4}}."}
D[91992]={"^Unleash voracious rats upon the targeted Scarlet Onslaught corpse%.%s*$","Solta ratos vorazes sobre o cadáver selecionado do Embate Escarlate."}
D[92001]={"^Mount the Onslaught Warhorse once its knight is dead%.%s*$","Monta o Cavalo de Guerra da Ofensiva quando seu cavaleiro estiver morto."}
D[92055]={"^Target an Onslaught raven priest and flash the mirror before them to steal their image%.%s*$","Selecione um Sacerdote Corvo do Embate e mostre o espelho diante dele para roubar sua imagem."}
D[92064]={"^Focus your will upon the target in order to get them to denounce their affiliation with the Scarlet Onslaught before they die%.%s*$","Concentre sua vontade no alvo para fazê-lo renunciar à sua ligação com o Embate Escarlate antes de morrer."}
D[92078]={"^Deals (.-) Frost damage%.  Only useful versus Onslaught Gryphon Riders%.%s*$","Causa {{1}} de dano de Gelo. Somente serve contra cavaleiros de grifos do Embate."}
D[92251]={"^Crushes your target, inflicting (.-)%% melee damage%.%s*$","Esmaga ao alvo e lhe causa {{1}}% do dano corpo a corpo."}
D[92252]={"^Riding an Onslaught Gryphon%.%s*$","Monta sobre o grifo do Embate selecionado."}
D[92253]={"^Call forth an Onslaught Gryphon%.%s*$","Evoca um grifo do Embate."}
D[92387]={"^Deals (.-)%% melee damage to your target, knocking them down for (.-)%.%s*$","causa {{1}}% do dano corpo a corpo ao alvo, e o derruba durante {{2}}."}
D[92528]={"^Unleashes the Meatpounder! Short range, maximum carnage!%s*$","Desata o Martelo de carne! Alcance curto, carnificina máxima!"}
D[92582]={"^The Seal of Onslaught inflicts an attack that ignores enemies armor%.%s*$","O Selo do Embate desfere um ataque ignorando a armadura dos inimigos."}
D[92584]={"^Each attack fuels the Reckless Onslaught, increasing the damage taken and damage dealt by the caster by (.-)%%  for (.-)%.%s*$","Cada ataque alimenta a Investida Temerária, aumentando em {{1}}% o dano causado e o dano recebido pelo conjurador durante {{2}}."}
D[92655]={"^Reduces the energy cost of your Cat form abilities by (.-)%% while in Cat form, and increases your total health by (.-)%% and causes your Mangle %(Bear%) and Maul abilities hit up to 3 maximum targets while in Bear form or Dire Bear form%. \n\nBerserk instantly clears all effects which cause loss of control of your character, and makes you immune to them for the duration%.%s*$","Reduz o custo de energia de sua habilidade Forma de Felino {{1}}% enquanto estiver baixo Forma de Felino e aumentando sua vida total {{2}}% e faz com que seu Ruptura (urso) e Magulhar atinjam até 3 alvos como máximo enquanto estiver baixo Forma de Urso ou Forma de Urso temível.\n\nRabia remove instantaneamente todos efeitos que provoquem perda de controle de seu personagem e faz você imune a eles enquanto dura."}
D[93053]={"^Apply the tincture to the corpse of one of the Scarlet Onslaught members at Onslaught Harbor%. Range is (.-) yards%. Cannot be used on the corpses of the Scarlet Onslaught within the cathedral or The Hidden Hollow%.%s*$","Aplique a tintura ao cadáver de um membro do Embate Escarlate no Porto do Embate. Alcance: {{1}} m. Não pode ser usada nos cadáveres do Embate Escarlate dentro da catedral nem em A Depressão Oculta."}
D[93235]={"^Fires a spike through the floor, impaling all targets within (.-) yards, dealing (.-) damage and knocking them up in the air%. This attack ignores armor%.%s*$","Dispara um espinho através do chão, empalando todos os alvos em um raio de {{1}} m, causando {{2}} de dano e lançando-os ao ar. Este ataque ignora a Armadura."}
D[93236]={"^Fires a spike through the floor, impaling all targets within (.-) yards, dealing (.-) damage and knocking them up in the air%.%s*$","Dispara um espinho através do chão, empalando todos os alvos em um raio de {{1}} m, causando {{2}} de dano e lançando-os ao ar."}
D[93394]={"^Deliver the Onslaught Gryphon to Uzo Deathcaller at Death's Rise%.%s*$","Entregue o Grifo de Batalha a Uzo Clama-morte na Ascensão da Morte."}
D[93410]={"^A vicious strike that deals talon damage plus (.-) modified by attack power and plagues the target, dealing (.-) Shadow damage over (.-)%.  Only useful versus Onslaught Gryphon Riders%.%s*$","Um golpe ferozes que causa dano de garra mais {{1}} modificados pelo poder de ataque apesta o alvo causando {{2}} de dano de Sombra durante {{3}}. Somente serve contra os cavaleiros de grifo do Embate."}
D[93438]={"^Unlocks Scarlet Onslaught Trunks%.%s*$","Destranca os Baús do Embate Escarlate."}
D[93462]={"^Attempts to decapitate all targets in melee range of the caster, causing (.-)%% weapon damage%.%s*$","Tenta decapitar todos os alvos no alcance corpo a corpo do conjurador, causando {{1}}% do dano da arma."}
D[94603]={"^Increases your attack power by (.-) but reduces your armor by (.-)%%%.  Lasts (.-)%.%s*$","Aumenta seu poder de ataque {{1}} mas reduz sua armadura {{2}}%. Dura {{3}}."}
D[95641]={"^Crushes enemy targets along the path of the tentacle's attack, dealing (.-) Physical damage to affected units%.%s*$","Esmaga aos alvos inimigos que se encontre o tentáculo pelo caminho, causa {{1}} de dano Físico às unidades afetadas."}
D[95858]={"^Crushes the target, inflicting (.-) damage%.%s*$","Esmaga o alvo e lhe causa {{1}} de dano."}
D[96601]={"^Impales a target from afar with your weapon, instantly killing them%.%s*$","Empala um alvo de longe com sua arma e o matar instantaneamente."}
D[96817]={"^A brutal strike that causes the target to bleed, taking additional damage over (.-)%.%s*$","Um golpe brutal que faz o alvo sangrar, sofrendo dano adicional ao longo de {{1}}."}
D[96856]={"^Impales the target upon your spear%.%s*$","Empala o alvo com sua lança."}
D[97328]={"^Enter the Shadow Dance for (.-), allowing the use of Sap, Garrote, Ambush, Cheap Shot, Premeditation, Pickpocket and Disarm Trap regardless of being stealthed%.%s*$","Entra na Dança das Sombras durante {{1}}, que permite o uso das habilidades Pancada, Garrote, Emboscada, Golpe Baixo, Premeditação, Roubar e Desativar armadilha embora não estiver em Furtividade."}
D[97591]={"^Generates 1 rage per 3 seconds%.%s*$","Gera 1 de raiva a cada 3 s."}
D[97671]={"^Reduces physical damage taken by (.-)%%%. Lasts (.-)%.%s*$","Reduz o dano Físico recebido {{1}}%. Dura {{2}}."}
D[98088]={"^Reduces the cooldown of your Bestial Wrath, Intimidation and Pet Special Abilities by (.-)%%%.%s*$","Reduz em {{1}}% a recarga de Ira Bestial, Intimidação e das habilidades especiais do seu mascote."}
D[98413]={"^While wielding a Two%-Handed Weapon, the chance to trigger |cFFFFFFFFWild Carnage|r is increased by (.-)%%%.\n\nRequires the |cffffffffWild Carnage|r talent%.%s*$","Enquanto empunhar uma arma de duas mãos, a chance de ativar |cFFFFFFFFCarne Assassina (Versão Selvagem)|r aumenta em {{1}}%.\n\nRequer o talento |cffffffffCarne Assassina (Versão Selvagem)|r."}
D[98517]={"^Calls a Bone Gryphon to serve as your flying mount%. May only be summoned and ridden within Onslaught Harbor%.%s*$","Evoca um Grifo Ósseo para servir como montaria voadora. Só pode ser evocado e usado no Porto da Ofensiva."}
