T[8380]={"^Increases ground speed by (.-)%%%. Increases flying speed by 280%%%.%s*$","Aumenta a velocidade em terreno em {{1}}%. Aumenta a velocidade de voo em 280%."}
T[9086]={"^Can be consumed by Ripper to deal additional damage%.%s*$","Pode ser consumido por Dilacerante para causar dano adicional."}
T[9416]={"^Gives melee auto attacks a (.-)%% chance to reset the cooldown of |cffffffffSavage Smash|r%.%s*$","Dá seus ataques automáticos de corpo a corpo {{1}}% de chance de reiniciar a recarga de |cffffffffaplastamento salvagem|r."}
T[9417]={"^Damage dealt by your next Savage Strike increased by (.-)%%%.%s*$","Aumenta o dano causado por seu próximo Assalto selvagem {{1}}%."}
T[9451]={"^Reduces your energy by 30 when you use berserker axe with surging fury lmao%s*$","Reduz seu energia em 30 quando usar machado berserker com fúria crescente jajaja"}
T[9525]={"^Causes |cffffffffMaximum Carnage|r to reduce your targets armor by (.-)%% for (.-)%.%s*$","Faz com que |cffffffffCarnificina Máxima|r reduza armadura de seus alvos em {{1}}% durante {{2}}."}
T[9526]={"^Movement speed increased by (.-)%%%. Immune to slows%.\n\nYour next Decapitate or Crush will consume this effect to critically strike%.%s*$","Velocidade de movimento aumentada em {{1}}%. Imune aos efeitos de Desaceleração.\n\nSeu próximo Decapitar ou Esmagar consumirá este efeito para realizar um acerto crítico."}
T[9528]={"^Increases the damage of |cffffffffRipper|r by (.-)%% and reduces its cooldown by (.-) sec%.%s*$","Aumenta o dano de |cffffffffRasgador|r em {{1}}% e reduz sua recarga em {{2}} s."}
T[9533]={"^Melee attack speed increased by (.-)%%, stacking (.-) times%.%s*$","Velocidade de ataque em corpo a corpo aumentada em {{1}}%, acumulando-se {{2}} vezes."}
T[9611]={"^Damage taken by the Barbarians Ancestral Strike increased by (.-)%%%. Stacks (.-) times%.%s*$","O dano recebido pelos Ancestrais Golpes aumenta em {{1}}%. Acumula {{2}} vezes."}
T[9627]={"^Increases the effects of |cffffffffSavage Rage|r by (.-)%%%.%s*$","Aumenta os efeitos de |cffffffffRaiva (Versão Selvagem)|r em {{1}}%."}
T[10163]={"^Next Smash or Barbaric Whirl deals (.-)%% more damage%.%s*$","O próximo Smash ou Redemoinho Bárbaro causa {{1}}% dano adicional."}
T[10200]={"^Increases melee haste by (.-)%% and reduces the cooldown of |cffffffffSavage Smash|r by (.-) sec%.%s*$","Aumenta a aceleração de corpo a corpo em {{1}}% e reduz a recarga de |cffffffffInvestida salvagem|r em {{2}} s."}
T[10222]={"^Increases the critical strike bonus damage of |cffffffffHeadhunter's Spear|r by (.-)%%%.%s*$","Aumenta o bônus de dano crítico de |cffffffffLança do Caçador de Cabecilhas|r em {{1}}%."}
T[10303]={"^Barbaric Strike consumes a Surging Fury stack to be usable while not enraged%.%s*$","acerto Bárbaro consome um acúmulo de Fúria Acelerada para ser utilizável inclusive quando não está enfurecido."}
T[10306]={"^Enraged%. Rapidly draining Energy%. Berserker Axe knocks enemies back, is free of cost, and guaranteed to critically strike%.\n\nCritical strikes reduce the cooldown of |cffffffffBerserker|r by (.-) sec%.%s*$","Enfurecido. Esgota rapidamente a Energia. O Machado Berserker empurra aos inimigos, é gratuita e garante um acerto crítico.\n\nOs acertos críticos reduzem a recarga de |cffffffffBerserker|r em {{1}} s."}
T[11095]={"^Your 6th Berserker Axe will cause you to launch a spear at the enemy after 1 sec%.%s*$","Seu 6º Machado Berserker faz você arremessar uma lança contra o inimigo após 1 s."}
T[11275]={"^Critical strike chance and damage of Decapitate increased by (.-)%%%.%s*$","A chance e o dano do acerto crítico de Decapitar aumentam em {{1}}%."}
T[11388]={"^Allows |cffffffffGutspiller|r and |cffffffffPiercing Throw|r to bounce to (.-) additional enemies%.%s*$","Permite que |cffffffffEstripador|r e |cffffffffArremesso Perfurante|r ricocheteiem em {{1}} inimigos adicionais."}
T[11389]={"^Your next 3 Axe Throws strike an additional nearby enemy%.%s*$","Seus próximos 3 Tiro de machado golpeia um inimigo adicional próximo."}
T[11390]={"^Deal an additional (.-)%% Weapon Damage to the target you inflicted with Carnage%.%s*$","Causa dano adicional de arma de {{1}}% o alvo ao que lhe você causou Carnificina."}
T[11866]={"^They say the banner of a true Blademaster does not simply follow the wind—it moves with the rhythm of combat itself, a crimson specter dancing in the storm of steel%.%s*$","Diz-se que o estandarte de um verdadeiro Mestre de Espadas não segue simplesmente ao vento—se move com o ritmo do combate mesmo, uma silhueta carmesim dançando na tempestade de aço."}
T[13455]={"^The Unrelenting Spirit is slowly decaying%.%.%.\n\nUpon death a Spiteful Burst is unleashed%.%s*$","O Espírito Incessante está decompondo-se lentamente.\n\nAo morrer se libertar uma Explosão Vingativa."}
T[13590]={"^Bleeding for (.-) damage every (.-) sec%. for (.-)%.%s*$","Faz o alvo sangrar, causando {{1}} de dano a cada {{2}} s durante {{3}}."}
T[13644]={"^Increases attack speed by (.-)%%%.\nPeriodically casts Shadow Bolt Volley%.%s*$","Aumenta a velocidade de ataque em {{1}}%.\nPeriodicamente lança Vontade sombras."}
T[13747]={"^Mangle can hit 3 targets and has no cooldown%. \nReduces the cost of Cat Form and Bear Form abilities by (.-)%%%.\nAbsorbs from Savage Defense is doubled%.\nCat combo point generators grant (.-) additional combo points %((.-) vs players%)%.%s*$","Destroçar pode golpear 3 alvos e não tem recarga.\nReduz o custo das habilidades em forma de Gato e Urso em {{1}}%.\nAs absorções de Defesa Selvagem são duplicadas.\nOs geradores de pontos de combo em forma de gato concedem {{2}} pontos adicionais ({{3}} contra jogadores)."}
T[14083]={"^Your next 3 Executes can be used regardless of the target's health, and its damage is increased by (.-)%% versus monsters%.%s*$","Seus próximos 3 Ejecuções pode ser usada independentemente de a vida do alvo, e seu dano aumenta em {{1}}% contra monstros."}
T[14249]={"^Increases Armor Penetration rating by (.-) for (.-)%. Can be stacked up to 5 times%.%s*$","Aumenta o índice de Penetração de Armadura em {{1}} durante {{2}}. Acumula até 5 vezes."}
T[14341]={"^Increases all threat you generate by (.-)%%%.%s*$","Aumenta toda a ameaça que gera em {{1}}%."}
T[14478]={"^Ripper has no cooldown below 8 uses%.%s*$","Rasgarper não tem recarga abaixo de 8 usos."}
T[14572]={"^Chance to trigger Ancestral Combat increased by (.-)%%%.%s*$","A chance de ativar Combate Ancestral aumenta em {{1}}%."}
T[14574]={"^Reduces the cooldown of |cffffffffWarlord|r by (.-) sec%.%s*$","Reduz a recarga de |cffffffffSenhor da Guerra|r em {{1}} s."}
T[14757]={"^Berserker Axe has no cooldown, but its range is reduced to 5 yards%. It also gains (.-)%% increased Critical Strike Chance%.%s*$","O Machado Berserker não tem recarga, mas seu alcance é reduzido a 5 metros. Também ganha {{1}}% de chance aumentada de acerto crítico."}
T[14762]={"^At 3 stacks, your movement speed is reduced by (.-)%% for (.-)%.%s*$","Com 3 acúmulos, sua velocidade de movimento é reduzida em {{1}}% durante {{2}}."}
T[14857]={"^Some abilities apply |cFFFFFFFFCarnage|r to the enemy%.\n\n|cFFFFFFFFCarnage|r  stacks are consumed by specific abilities for additional effectiveness%.%s*$","Algumas habilidades aplicam |cFFFFFFFFCarnificina|r ao inimigo.\n\nAcúmulos de |cFFFFFFFFCarnificina|r são consumidos por habilidades específicas para aumentar sua eficácia."}
T[14921]={"^Increases Energy by 30%%%.%s*$","Aumenta a Energia em 30%."}
T[14923]={"^Reduces the Energy cost of |cffffffffAxe Throw|r by up to (.-)%% based on missing Energy%.%s*$","Reduz o custo de Energia de |cffffffffLançar machados|r em até {{1}}%, com base na Energia que falta."}
T[14930]={"^Your Barbaric Whirl ability now causes your Honored Ancestor minion to perform a similar whirlwind attack, dealing Physical damage to enemies around it based on your Agility, and your Spirit%.\n\nIn addition, using Whirling Advance will cause your Honored Ancestor to perform the same action%.%s*$","Sua habilidade Redemoinho Bárbaro agora faz seu lacaio Ancestral Honrado realizar um ataque de redemoinho semelhante, causando dano Físico aos inimigos ao redor com base em sua Agilidade e Espírito.\n\nAlém disso, usar Avanço Giratório faz seu Ancestral Honrado executar a mesma ação."}
T[14937]={"^Increases the duration of |cffffffffWrist Snap|r by (.-) sec and reduces its cooldown by (.-) sec%.%s*$","Aumenta a duração de |cffffffffQuebra-Pulso|r em {{1}} s e reduz sua recarga em {{2}} s."}
T[14980]={"^Causes |cffffffffBrutal Swing|r and |cffffffffSavage Smash|r to increase the damage of your next |cffffffffWrecker|r by (.-)%% for (.-)%.\n\nCan only occur once every 30 sec%.%s*$","Faz com que |cffffffffTalho Brutal|r e |cffffffffSavage Smash|r aumento dano de seu próximo |cffffffffDestruidor|r em {{1}}% durante {{2}}.\n\nSó pode acontecer uma vez a cada 30 s."}
T[14981]={"^Keg Smash applies Blind Stupor to the enemy%.%s*$","Destruidor de barris aplica Estupor cego inimigo."}
T[14982]={"^While at or below 35%% maximum health, you now take (.-)%% reduced damage and gain a (.-)%% reduced chance to be critically struck%.%s*$","Enquanto estiver a ou menos do 35% de vida máxima, agora recebe {{1}}% do dano reduzidos e obtém uma diminuição de {{2}}% na chance de ser atingido criticamente."}
T[14983]={"^Auto attacks, |cFFFFFFFFStorm of Steel|r and |cffffffffThrow Weapon|r generate (.-) Energy and heal you for (.-)%.%s*$","Os ataques automáticos, |cFFFFFFFFTempestade de Aço|r e |cffffffffLançar Arma|r geram {{1}} Energia e cura você em {{2}}."}
T[14984]={"^Auto attacks and |cffffffffThrow Weapon|r generate (.-) Energy and heal you for (.-)%.%s*$","Os ataques automáticos e |cffffffffLançar Arma|r geram {{1}} Energia e cura você em {{2}}."}
T[14991]={"^|cffffffffSmash|r now grants |cffffffffMounting Fury|r for (.-), stacking (.-) times%.%s*$","|cffffffffEsmagar|r agora concede |cffffffffFúria Crescente|r durante {{1}}, acumula {{2}} vezes."}
T[14992]={"^Each time you use Raging Strike you gain a stack of Mounting Fury for (.-), reducing the cooldown of Raging Strike by (.-) sec, stacks up to 4 times%.%s*$","Cada vez que você usa Golpe Furioso, recebe um acúmulo de Fúria Crescente durante {{1}}, reduzindo em {{2}} s a recarga de Golpe Furioso. Acumula até 4 vezes."}
T[15032]={"^The Barbarian deals an additional 50%% Weapon Damage to you on hit!%s*$","O Bárbaro causa a você 50% adicional de dano da arma em cada acerto!"}
T[15180]={"^You may use Execute regardless of target's health, and its damage is increased by (.-)%% versus monsters%.%s*$","Você pode usar Execução independentemente da vida do alvo e seu dano aumenta em {{1}}% contra monstros."}
T[15642]={"^Attempts to decapitate the target, throwing an axe after it with such force it inflicts (.-)%% Weapon damage and knocks the target back%. Damage is reduced as further the target is away from the caster%.%s*$","Tenta decapitar o alvo, arrojando um machado com tanta força que causa {{1}}% de dano da arma e afasta ao alvo. O dano é reduzido conforme o alvo está mais longe do conjurador."}
T[17163]={"^Restores a charge of Unrelenting Wrath at 5 stacks%.%s*$","Recupera uma carga de Raiva Incessante com 5 acúmulos."}
T[17164]={"^Your continuous Bestial Assault restores a charge of Unrelenting Wrath%.%s*$","Seu Ataque Bestial continuo recupera uma carga de Raiva Incessante."}
T[17401]={"^Increases the duration of Carnage Incarnate by 100%% while in bear or dire bear form%s*$","Aumenta em 100% a duração de Carnificina Encarnada enquanto você estiver em Forma de Urso ou Forma de Urso Atroz."}
